async function checkNatsHealth() {
  try {
    const testId = `health-${Date.now()}`;
    const received = new Promise(resolve => {
      const sub = nc.subscribe(`health.${testId}`, () => {
        sub.unsubscribe();
        resolve(true);
      });
    });
    await nc.publish(`health.${testId}`, { ts: Date.now() });
    return (await Promise.race([received, Promise.resolve(false)])) ? 'ok' : 'down';
  } catch { return 'down'; }
}

